import{_ as e,o as t,c as r,ae as s}from"./chunks/framework.Dh1jimFm.js";const m=JSON.parse('{"title":"Supervertaler Workbench","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function o(i,a,l,d,c,p){return t(),r("div",null,a[0]||(a[0]=[s('<h1 id="supervertaler-workbench" tabindex="-1">Supervertaler Workbench <a class="header-anchor" href="#supervertaler-workbench" aria-label="Permalink to &quot;Supervertaler Workbench&quot;">​</a></h1><p>Supervertaler Workbench is a standalone desktop CAT (Computer-Assisted Translation) tool built with Python and PyQt6. It is free and open source (MIT licence) and runs on Windows, macOS, and Linux.</p><p>Supervertaler Workbench gives you AI-powered translation, full translation memory, terminology management, quality assurance, and import/export for common file formats — all in one application, without a subscription.</p><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><h3 id="ai-translation" tabindex="-1">AI Translation <a class="header-anchor" href="#ai-translation" aria-label="Permalink to &quot;AI Translation&quot;">​</a></h3><p>Translate single segments or entire files using any major LLM provider — OpenAI, Anthropic, Google Gemini, Mistral, Grok, DeepSeek, and more. Domain-specific prompts and a built-in Prompt Library help you get consistent, high-quality output. Run models locally with Ollama for a fully offline workflow.</p><h3 id="translation-memory" tabindex="-1">Translation Memory <a class="header-anchor" href="#translation-memory" aria-label="Permalink to &quot;Translation Memory&quot;">​</a></h3><p>Store and reuse confirmed translations with fuzzy matching. Import existing TMX files to seed your TM, and let SuperMemory surface the best match automatically.</p><h3 id="glossaries-termlens" tabindex="-1">Glossaries &amp; TermLens <a class="header-anchor" href="#glossaries-termlens" aria-label="Permalink to &quot;Glossaries &amp; TermLens&quot;">​</a></h3><p>Create and manage glossaries in Supervertaler&#39;s SQLite <code>.db</code> format. TermLens highlights matched terms directly in the segment grid so you never miss a term. Extract new terms automatically from your source text.</p><h3 id="import-export" tabindex="-1">Import &amp; Export <a class="header-anchor" href="#import-export" aria-label="Permalink to &quot;Import &amp; Export&quot;">​</a></h3><p>Open DOCX, TXT, SDLXLIFF, bilingual tables, and multi-file projects. Export translations back to the original format with one click.</p><h3 id="superlookup" tabindex="-1">SuperLookup <a class="header-anchor" href="#superlookup" aria-label="Permalink to &quot;SuperLookup&quot;">​</a></h3><p>A combined lookup panel showing TM matches, glossary hits, machine translation, and web resources side by side — all driven by the current segment.</p><h3 id="quality-assurance" tabindex="-1">Quality Assurance <a class="header-anchor" href="#quality-assurance" aria-label="Permalink to &quot;Quality Assurance&quot;">​</a></h3><p>Built-in spellcheck, tag validation, and non-translatable detection catch common errors before you deliver.</p><hr><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Details</th></tr></thead><tbody><tr><td><strong>Operating System</strong></td><td>Windows 10/11, macOS 12+, or Linux</td></tr><tr><td><strong>Python</strong></td><td>3.11 or later</td></tr><tr><td><strong>RAM</strong></td><td>4 GB recommended</td></tr><tr><td><strong>Disk space</strong></td><td>~200 MB</td></tr></tbody></table><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><div class="sv-cards"><a class="sv-card" href="/get-started/installation"><span class="sv-card-title">Getting Started</span><span class="sv-card-desc">Install and set up Supervertaler →</span></a><a class="sv-card" href="/ai-translation/overview"><span class="sv-card-title">AI Translation</span><span class="sv-card-desc">Set up providers and translate →</span></a><a class="sv-card" href="/glossaries/basics"><span class="sv-card-title">Glossaries</span><span class="sv-card-desc">Create and manage glossaries →</span></a><a class="sv-card" href="/translation-memory/basics"><span class="sv-card-title">Translation Memory</span><span class="sv-card-desc">Store and reuse translations →</span></a><a class="sv-card" href="/import-export/formats"><span class="sv-card-title">Import &amp; Export</span><span class="sv-card-desc">Supported file formats →</span></a><a class="sv-card" href="/editor/keyboard-shortcuts"><span class="sv-card-title">Keyboard Shortcuts</span><span class="sv-card-desc">All shortcuts at a glance →</span></a></div>',23)]))}const u=e(n,[["render",o]]);export{m as __pageData,u as default};
